-- SIMULATED refinery production + energy data (NOT real IOCL data)
-- Run this whole file once in MySQL Workbench. It creates database refinery_db and table refinery.
DROP DATABASE IF EXISTS refinery_db;
CREATE DATABASE refinery_db;
USE refinery_db;

CREATE TABLE refinery (
    record_id INT PRIMARY KEY,
    date DATE,
    unit_id VARCHAR(5),
    unit_name VARCHAR(50),
    crude_blend VARCHAR(20),
    crude_api_gravity DECIMAL(5,1),
    crude_sulfur_pct DECIMAL(4,2),
    design_capacity_tpd INT,
    feed_processed_tonnes DECIMAL(12,1),
    capacity_utilization_pct DECIMAL(6,2),
    product_output_tonnes DECIMAL(12,1),
    yield_pct DECIMAL(6,2),
    fuel_gas_gj DECIMAL(14,1),
    electricity_mwh DECIMAL(12,2),
    steam_tonnes DECIMAL(12,1),
    total_energy_gj DECIMAL(14,1),
    energy_intensity_gj_per_tonne DECIMAL(8,3),
    energy_cost_inr DECIMAL(16,0),
    data_source VARCHAR(60)
);


SELECT COUNT(*) AS total_rows FROM refinery;
